/* main.css */
@tailwind base;
@tailwind components;
@tailwind utilities;

/* Using @apply to create a reusable CSS class (Use sparingly!) */
@layer components {
  .btn-primary {
    @apply bg-blue-600 text-white font-semibold py-2 px-4 rounded shadow;
    @apply hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2;
    @apply transition duration-150 ease-in-out;
  }
}

/* In standard HTML */
<button class="btn-primary">Submit</button>
